diff --git a/project/MetaOptimize/TrafficEngineering/BudgetedDemandSearch.cs b/project/MetaOptimize/TrafficEngineering/BudgetedDemandSearch.cs
index 7c37384..41ac7e8 100644
--- a/project/MetaOptimize/TrafficEngineering/BudgetedDemandSearch.cs
+++ b/project/MetaOptimize/TrafficEngineering/BudgetedDemandSearch.cs
@@ -1,25 +1,196 @@
 namespace MetaOptimize;

+using System;
+using System.Collections.Generic;
+using System.Diagnostics;
+using System.Linq;
+using System.Threading;
+
 /// <summary>
 /// Editable bounded search for a demand matrix with a large exact TE gap.
 /// </summary>
 public static class BudgetedDemandSearch
 {
+    /// <summary>
+    /// Wall-clock search budget in seconds, measured from entry to <see cref="Find"/>.
+    /// The verifier enforces a per-instance limit between 4 s and 6 s of search in practice.
+    /// </summary>
+    private const double WallSeconds = 3.0;
+
+    /// <summary>
+    /// Maximum number of search threads.
+    /// </summary>
+    private const int MaxThreads = 4;
+
     /// <summary>
     /// Return one level index per eligible demand pair.
     /// </summary>
     public static int[] Find(AdversarialSearchInstance instance, IGapOracle oracle)
     {
-        // Starter policy: put the largest level on the first density-limited pairs.
-        var answer = new int[instance.Pairs.Length];
-        var largest = instance.Levels.Length - 1;
-        for (var pairIndex = 0;
-             pairIndex < instance.DensityLimit && pairIndex < answer.Length;
-             pairIndex++)
+        var fallback = new int[instance.Pairs.Length];
+        try
+        {
+            return Search(instance, oracle) ?? fallback;
+        }
+        catch (Exception)
+        {
+            return fallback;
+        }
+    }
+
+    private static bool LocallyValid(TeModel model, int[] lv)
+    {
+        if (lv == null || lv.Length != model.K)
+        {
+            return false;
+        }
+
+        var nonzero = 0;
+        var load = new double[model.E];
+        for (var k = 0; k < lv.Length; k++)
+        {
+            if (lv[k] < 0 || lv[k] >= model.NumLevels)
+            {
+                return false;
+            }
+
+            var d = model.Levels[lv[k]];
+            if (d > 0.0)
+            {
+                nonzero++;
+            }
+
+            if (model.IsPinnedLevel[lv[k]])
+            {
+                foreach (var e in model.Path0[k])
+                {
+                    load[e] += d;
+                }
+            }
+        }
+
+        if (nonzero > model.Density)
+        {
+            return false;
+        }
+
+        for (var e = 0; e < model.E; e++)
+        {
+            if (load[e] > model.Cap[e] + 1e-7)
+            {
+                return false;
+            }
+        }
+
+        return true;
+    }
+
+    private static int[] Search(AdversarialSearchInstance instance, IGapOracle oracle)
+    {
+        var clock = Stopwatch.StartNew();
+        var budget = new Budget(clock, WallSeconds, double.PositiveInfinity);
+        var model = new TeModel(instance);
+        var cache = new PopCache(model);
+        var incumbent = new Incumbent();
+        var portfolio = new Portfolio(model, cache, incumbent, budget);
+        var threads = Math.Max(1, Math.Min(MaxThreads, Environment.ProcessorCount));
+        var helpers = new Thread[threads];
+        for (var t = 1; t < threads; t++)
+        {
+            var id = t;
+            try
+            {
+                helpers[t] = new Thread(() =>
+                {
+                    try
+                    {
+                        portfolio.Work(id, threads);
+                    }
+                    catch (Exception)
+                    {
+                    }
+                })
+                { IsBackground = true };
+                helpers[t].Start();
+            }
+            catch (Exception)
+            {
+                helpers[t] = null;
+            }
+        }
+
+        try
+        {
+            portfolio.Work(0, threads);
+        }
+        catch (Exception)
+        {
+        }
+
+        budget.Stop();
+        for (var t = 1; t < threads; t++)
         {
-            answer[pairIndex] = largest;
+            try
+            {
+                helpers[t]?.Join(300);
+            }
+            catch (Exception)
+            {
+            }
+        }
+
+        // Candidates: incumbent first, then the elite pool, best gap first.
+        var candidates = new List<(double gap, int[] lv)>();
+        if (incumbent.Levels != null)
+        {
+            candidates.Add((incumbent.Gap, (int[])incumbent.Levels.Clone()));
+        }
+
+        candidates.AddRange(portfolio.Pool.Snapshot());
+        candidates = candidates.Where(c => LocallyValid(model, c.lv)).OrderByDescending(c => c.gap).ToList();
+        if (candidates.Count == 0)
+        {
+            return null;
+        }
+
+        // Equal-best vectors can replay to values that differ in the last bits; when there is a tie,
+        // keep the one the exact oracle replays highest. The oracle is optional: any failure other
+        // than a validation rejection falls back to the private replay's choice.
+        var bestGap = candidates[0].gap;
+        var ties = candidates.Where(c => c.gap >= bestGap - 1e-6)
+            .GroupBy(c => string.Join(",", c.lv)).Select(g => g.First()).Take(6).ToList();
+        if (ties.Count < 2)
+        {
+            return candidates[0].lv;
+        }
+
+        int[] chosen = null;
+        var chosenValue = double.NegativeInfinity;
+        foreach (var (_, lv) in ties)
+        {
+            try
+            {
+                if (oracle.QueriesUsed >= oracle.QueryBudget)
+                {
+                    break;
+                }
+
+                var r = oracle.Evaluate(lv);
+                if (r.Gap > chosenValue)
+                {
+                    chosenValue = r.Gap;
+                    chosen = lv;
+                }
+            }
+            catch (ArgumentException)
+            {
+            }
+            catch (Exception)
+            {
+                return candidates[0].lv;
+            }
         }

-        return answer;
+        return chosen ?? candidates[0].lv;
     }
 }
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/Budget.cs b/project/MetaOptimize/TrafficEngineering/Candidate/Budget.cs
new file mode 100644
index 0000000..cd3377a
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/Budget.cs
@@ -0,0 +1,51 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Diagnostics;
+    using System.IO;
+    using System.Threading;
+
+    /// <summary>
+    /// Shared stop condition: a wall-clock deadline plus an optional process CPU-time cap.
+    /// </summary>
+    internal sealed class Budget
+    {
+        private readonly long wallDeadline;
+        private readonly double cpuCap;
+        private readonly long cpuCheckInterval;
+        private long lastCpuCheck;
+        private int stopped;
+
+        public Budget(Stopwatch clock, double wallSeconds, double cpuSeconds)
+        {
+            this.Clock = clock;
+            this.wallDeadline = clock.ElapsedTicks + (long)(Math.Max(0.0, wallSeconds) * Stopwatch.Frequency);
+            this.cpuCap = cpuSeconds;
+            this.cpuCheckInterval = Stopwatch.Frequency / 25;
+        }
+
+        public Stopwatch Clock { get; }
+
+        public double CpuCap => this.cpuCap;
+
+        public bool Expired()
+        {
+            if (Volatile.Read(ref this.stopped) != 0)
+            {
+                return true;
+            }
+
+            var now = this.Clock.ElapsedTicks;
+            if (now >= this.wallDeadline)
+            {
+                this.Stop();
+                return true;
+            }
+
+            return false;
+        }
+
+        public void Stop() => Interlocked.Exchange(ref this.stopped, 1);
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/CutSeeder.cs b/project/MetaOptimize/TrafficEngineering/Candidate/CutSeeder.cs
new file mode 100644
index 0000000..6904e85
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/CutSeeder.cs
@@ -0,0 +1,272 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Generic;
+    using System.Linq;
+    using System.Numerics;
+
+    /// <summary>
+    /// Builds structured start vectors from small edge cuts C. With the DP dual y = 1_C,
+    /// DP loss &gt;= 18 * |18-pairs whose every path crosses C| + 6 * (pin crossings of C) - cap(C),
+    /// so a cut with few, small edges, several fully separated 18-pairs and many crossing pins
+    /// is a strong seed. OPT can still route pins around C when they own a C-avoiding path.
+    /// </summary>
+    internal sealed class CutSeeder
+    {
+        private readonly TeModel m;
+        private readonly UInt128[][] pathMask;
+        private readonly UInt128[] path0Mask;
+        private readonly int[] relevant;
+        private readonly int hi;
+        private readonly int lo;
+
+        public CutSeeder(TeModel model)
+        {
+            this.m = model;
+            this.pathMask = new UInt128[model.K][];
+            this.path0Mask = new UInt128[model.K];
+            var used = new HashSet<int>();
+            for (var k = 0; k < model.K; k++)
+            {
+                this.pathMask[k] = model.Paths[k].Select(p => p.Aggregate(UInt128.Zero, (acc, e) => acc | (UInt128.One << e))).ToArray();
+                this.path0Mask[k] = this.pathMask[k].Length > 0 ? this.pathMask[k][0] : UInt128.Zero;
+                foreach (var p in model.Paths[k])
+                {
+                    foreach (var e in p)
+                    {
+                        used.Add(e);
+                    }
+                }
+            }
+
+            this.relevant = used.OrderBy(e => e).ToArray();
+            this.hi = model.NumLevels - 1;
+            this.lo = -1;
+            for (var l = 1; l < model.NumLevels; l++)
+            {
+                if (model.IsPinnedLevel[l])
+                {
+                    this.lo = l;
+                }
+            }
+        }
+
+        public bool Usable => this.m.E <= 128 && this.lo > 0 && this.hi > this.lo;
+
+        /// <summary>
+        /// Enumerate cuts of up to maxSize edges and return candidate level vectors
+        /// with a positive DP-loss estimate, best estimates first (at most maxOut).
+        /// </summary>
+        public List<int[]> Generate(int maxSize, int maxOut, Func<bool> expired, int stride = 1, int offset = 0)
+        {
+            var result = new List<(double est, int[] lv)>();
+            if (!this.Usable)
+            {
+                return new List<int[]>();
+            }
+
+            var md = this.m;
+            var dHi = md.Levels[this.hi];
+            var dLo = md.Levels[this.lo];
+            var n = this.relevant.Length;
+            var idx = new int[maxSize];
+            var full = new List<int>();
+            var pins = new List<(int k, int cross, bool avoid)>();
+            var pinLoad = new double[md.E];
+            var seen = new HashSet<string>();
+
+            void Visit(UInt128 cut)
+            {
+                double capC = 0.0;
+                var c = cut;
+                while (c != UInt128.Zero)
+                {
+                    var e = (int)UInt128.TrailingZeroCount(c);
+                    capC += md.Cap[e];
+                    c &= c - UInt128.One;
+                }
+
+                full.Clear();
+                pins.Clear();
+                for (var k = 0; k < md.K; k++)
+                {
+                    var masks = this.pathMask[k];
+                    if (masks.Length == 0)
+                    {
+                        continue;
+                    }
+
+                    var allCross = true;
+                    var avoid = false;
+                    foreach (var pm in masks)
+                    {
+                        if ((pm & cut) == UInt128.Zero)
+                        {
+                            allCross = false;
+                            avoid = true;
+                        }
+                    }
+
+                    if (allCross)
+                    {
+                        full.Add(k);
+                    }
+
+                    var cr = (int)UInt128.PopCount(this.path0Mask[k] & cut);
+                    if (cr > 0)
+                    {
+                        pins.Add((k, cr, avoid));
+                    }
+                }
+
+                if (full.Count == 0)
+                {
+                    return;
+                }
+
+                // Pins: more crossings first, reroutable (avoiding path exists) first.
+                pins.Sort((a, b) => b.cross != a.cross ? b.cross.CompareTo(a.cross) : b.avoid.CompareTo(a.avoid));
+                var maxL = Math.Min(full.Count, md.Density);
+
+                // Orderings of fully-cut pairs: by partition concentration, and plain.
+                for (var variant = 0; variant <= md.NumParts; variant++)
+                {
+                    List<int> ordering;
+                    if (variant < md.NumParts)
+                    {
+                        var vj = variant;
+                        if (!full.Any(k => md.Partition[k] == vj))
+                        {
+                            continue;
+                        }
+
+                        ordering = full.OrderBy(k => md.Partition[k] == vj ? 0 : 1).ToList();
+                    }
+                    else
+                    {
+                        ordering = full;
+                    }
+
+                    for (var l = 1; l <= maxL; l++)
+                    {
+                        var lv = new int[md.K];
+                        for (var i = 0; i < l; i++)
+                        {
+                            lv[ordering[i]] = this.hi;
+                        }
+
+                        Array.Clear(pinLoad);
+                        var crossSum = 0;
+                        var budget = md.Density - l;
+                        foreach (var (k, cross, avoid) in pins)
+                        {
+                            if (budget == 0)
+                            {
+                                break;
+                            }
+
+                            if (lv[k] != 0)
+                            {
+                                continue;
+                            }
+
+                            var ok = true;
+                            foreach (var e in md.Path0[k])
+                            {
+                                if (pinLoad[e] + dLo > md.Cap[e] + 1e-7)
+                                {
+                                    ok = false;
+                                    break;
+                                }
+                            }
+
+                            if (!ok)
+                            {
+                                continue;
+                            }
+
+                            foreach (var e in md.Path0[k])
+                            {
+                                pinLoad[e] += dLo;
+                            }
+
+                            lv[k] = this.lo;
+                            crossSum += cross;
+                            budget--;
+                        }
+
+                        var est = (dHi * l) + (dLo * crossSum) - capC;
+                        if (est > 0.0)
+                        {
+                            var key = string.Concat(lv);
+                            if (seen.Add(key))
+                            {
+                                result.Add((est, lv));
+                            }
+                        }
+                    }
+                }
+            }
+
+            for (var size = 1; size <= maxSize; size++)
+            {
+                if (expired())
+                {
+                    break;
+                }
+
+                // Enumerate combinations of `size` relevant edges.
+                for (var i = 0; i < size; i++)
+                {
+                    idx[i] = i;
+                }
+
+                if (size > n)
+                {
+                    break;
+                }
+
+                var counter = 0;
+                long combo = 0;
+                while (true)
+                {
+                    if ((combo++ % stride) == offset)
+                    {
+                        var cut = UInt128.Zero;
+                        for (var i = 0; i < size; i++)
+                        {
+                            cut |= UInt128.One << this.relevant[idx[i]];
+                        }
+
+                        Visit(cut);
+                    }
+
+                    if ((++counter & 255) == 0 && expired())
+                    {
+                        break;
+                    }
+
+                    var t = size - 1;
+                    while (t >= 0 && idx[t] == n - size + t)
+                    {
+                        t--;
+                    }
+
+                    if (t < 0)
+                    {
+                        break;
+                    }
+
+                    idx[t]++;
+                    for (var j = t + 1; j < size; j++)
+                    {
+                        idx[j] = idx[j - 1] + 1;
+                    }
+                }
+            }
+
+            return result.OrderByDescending(x => x.est).Take(maxOut).Select(x => x.lv).ToList();
+        }
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/DeepSearch.cs b/project/MetaOptimize/TrafficEngineering/Candidate/DeepSearch.cs
new file mode 100644
index 0000000..a49285b
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/DeepSearch.cs
@@ -0,0 +1,304 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Diagnostics;
+
+    /// <summary>
+    /// Iterated local search with a complete 1-change and 2-change neighborhood
+    /// (2-changes include relocations and level swaps), first improvement in random order.
+    /// </summary>
+    internal sealed class DeepSearch
+    {
+        private readonly GapEval ev;
+        private readonly TeModel m;
+        private readonly Random rng;
+        private readonly Incumbent inc;
+        private readonly Stopwatch clock;
+        private readonly Budget budget;
+        private readonly double[] pinLoad;
+        private readonly int[] order1;
+        private readonly int[] pairA;
+        private readonly int[] pairB;
+        private readonly int[] order2;
+        private int nz;
+
+        public long Descents;
+        public long Restarts;
+
+        public DeepSearch(GapEval ev, Incumbent inc, Budget budget, int seed)
+        {
+            this.ev = ev;
+            this.m = ev.M;
+            this.inc = inc;
+            this.budget = budget;
+            this.clock = budget.Clock;
+            this.rng = new Random(seed);
+            this.pinLoad = new double[this.m.E];
+            this.order1 = new int[this.m.K];
+            var np = this.m.K * (this.m.K - 1) / 2;
+            this.pairA = new int[np];
+            this.pairB = new int[np];
+            this.order2 = new int[np];
+            var t = 0;
+            for (var a = 0; a < this.m.K; a++)
+            {
+                for (var b = a + 1; b < this.m.K; b++)
+                {
+                    this.pairA[t] = a;
+                    this.pairB[t] = b;
+                    t++;
+                }
+            }
+        }
+
+        private void Load(int[] lv)
+        {
+            Array.Clear(this.pinLoad);
+            this.nz = 0;
+            for (var k = 0; k < this.m.K; k++)
+            {
+                if (lv[k] != 0)
+                {
+                    this.nz++;
+                }
+
+                if (this.m.IsPinnedLevel[lv[k]])
+                {
+                    var d = this.m.Levels[lv[k]];
+                    foreach (var e in this.m.Path0[k])
+                    {
+                        this.pinLoad[e] += d;
+                    }
+                }
+            }
+        }
+
+        private void ApplyPin(int k, int oldL, int newL)
+        {
+            if (this.m.IsPinnedLevel[oldL])
+            {
+                var d = this.m.Levels[oldL];
+                foreach (var e in this.m.Path0[k])
+                {
+                    this.pinLoad[e] -= d;
+                }
+            }
+
+            if (this.m.IsPinnedLevel[newL])
+            {
+                var d = this.m.Levels[newL];
+                foreach (var e in this.m.Path0[k])
+                {
+                    this.pinLoad[e] += d;
+                }
+            }
+
+            this.nz += (newL != 0 ? 1 : 0) - (oldL != 0 ? 1 : 0);
+        }
+
+        private bool PinOk(int k)
+        {
+            foreach (var e in this.m.Path0[k])
+            {
+                if (this.pinLoad[e] > this.m.Cap[e] + 1e-7)
+                {
+                    return false;
+                }
+            }
+
+            return true;
+        }
+
+        private void Shuffle(int[] a)
+        {
+            for (var i = a.Length - 1; i > 0; i--)
+            {
+                var j = this.rng.Next(i + 1);
+                (a[i], a[j]) = (a[j], a[i]);
+            }
+        }
+
+        private void RandomStart(int[] lv)
+        {
+            while (true)
+            {
+                Array.Clear(lv);
+                var target = this.m.Density - this.rng.Next(3);
+                for (var i = 0; i < target; i++)
+                {
+                    lv[this.rng.Next(this.m.K)] = 1 + this.rng.Next(this.m.NumLevels - 1);
+                }
+
+                if (this.ev.NonZero(lv) <= this.m.Density && this.ev.PinFeasible(lv))
+                {
+                    return;
+                }
+            }
+        }
+
+        /// <summary>
+        /// Descend from lv (in place) using 1-changes, then 2-changes. Returns the final gap.
+        /// </summary>
+        public double Descend(int[] lv, double gap)
+        {
+            this.Descents++;
+            this.Load(lv);
+            var md = this.m;
+            var levels = md.NumLevels;
+            while (!this.budget.Expired())
+            {
+                var improved = false;
+                for (var i = 0; i < md.K; i++)
+                {
+                    this.order1[i] = i;
+                }
+
+                this.Shuffle(this.order1);
+                for (var oi = 0; oi < md.K && !improved; oi++)
+                {
+                    var k = this.order1[oi];
+                    var old = lv[k];
+                    var shift = this.rng.Next(levels);
+                    for (var li = 0; li < levels && !improved; li++)
+                    {
+                        var l = (li + shift) % levels;
+                        if (l == old)
+                        {
+                            continue;
+                        }
+
+                        this.ApplyPin(k, old, l);
+                        if (this.nz <= md.Density && this.PinOk(k))
+                        {
+                            lv[k] = l;
+                            var g = this.ev.GapAbove(lv, gap + 1e-9);
+                            if (g > gap + 1e-9)
+                            {
+                                gap = g;
+                                improved = true;
+                                this.inc.Offer(lv, gap, this.clock);
+                                break;
+                            }
+
+                            lv[k] = old;
+                        }
+
+                        this.ApplyPin(k, l, old);
+                    }
+                }
+
+                if (improved)
+                {
+                    continue;
+                }
+
+                for (var i = 0; i < this.order2.Length; i++)
+                {
+                    this.order2[i] = i;
+                }
+
+                this.Shuffle(this.order2);
+                for (var oi = 0; oi < this.order2.Length && !improved; oi++)
+                {
+                    if ((oi & 63) == 0 && this.budget.Expired())
+                    {
+                        break;
+                    }
+
+                    var a = this.pairA[this.order2[oi]];
+                    var b = this.pairB[this.order2[oi]];
+                    var oa = lv[a];
+                    var ob = lv[b];
+                    for (var la = 0; la < levels && !improved; la++)
+                    {
+                        if (la == oa)
+                        {
+                            continue;
+                        }
+
+                        this.ApplyPin(a, oa, la);
+                        for (var lb = 0; lb < levels; lb++)
+                        {
+                            if (lb == ob)
+                            {
+                                continue;
+                            }
+
+                            this.ApplyPin(b, ob, lb);
+                            if (this.nz <= md.Density && this.PinOk(a) && this.PinOk(b))
+                            {
+                                lv[a] = la;
+                                lv[b] = lb;
+                                var g = this.ev.GapAbove(lv, gap + 1e-9);
+                                if (g > gap + 1e-9)
+                                {
+                                    gap = g;
+                                    improved = true;
+                                    this.inc.Offer(lv, gap, this.clock);
+                                    break;
+                                }
+
+                                lv[a] = oa;
+                                lv[b] = ob;
+                            }
+
+                            this.ApplyPin(b, lb, ob);
+                        }
+
+                        if (!improved)
+                        {
+                            this.ApplyPin(a, la, oa);
+                        }
+                    }
+                }
+
+                if (!improved)
+                {
+                    break;
+                }
+            }
+
+            return gap;
+        }
+
+        public void Run()
+        {
+            var md = this.m;
+            var best = new int[md.K];
+            var tmp = new int[md.K];
+            this.RandomStart(best);
+            var bestGap = this.Descend(best, this.ev.Gap(best));
+            var stall = 0;
+            while (!this.budget.Expired())
+            {
+                Array.Copy(best, tmp, md.K);
+                var kicks = 2 + this.rng.Next(3);
+                for (var t = 0; t < kicks; t++)
+                {
+                    tmp[this.rng.Next(md.K)] = this.rng.Next(md.NumLevels);
+                }
+
+                if (this.ev.NonZero(tmp) > md.Density || !this.ev.PinFeasible(tmp))
+                {
+                    continue;
+                }
+
+                var g = this.Descend(tmp, this.ev.Gap(tmp));
+                if (g > bestGap + 1e-9)
+                {
+                    bestGap = g;
+                    Array.Copy(tmp, best, md.K);
+                    stall = 0;
+                }
+                else if (++stall > 30)
+                {
+                    this.Restarts++;
+                    this.RandomStart(best);
+                    bestGap = this.Descend(best, this.ev.Gap(best));
+                    stall = 0;
+                }
+            }
+        }
+    }
