--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/ExactEnum.cs
@@ -0,0 +1,342 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Generic;
+    using System.Diagnostics;
+    using System.Linq;
+    using System.Threading;
+
+    /// <summary>
+    /// Branch-and-bound enumeration over level vectors. Pairs are ordered partition by partition,
+    /// so the POP loss (total - POP) decomposes and admits exact per-partition completion bounds.
+    /// Leaves are filtered by DP loss before the OPT LP is solved.
+    /// </summary>
+    internal sealed class ExactEnum
+    {
+        private readonly TeModel m;
+        private readonly int levels;
+        private readonly int budget;
+        private readonly int[] order;          // global DFS order of pairs
+        private readonly int[] posPart;        // position -> partition
+        private readonly int[] posInPart;      // position -> index within its partition
+        private readonly int[] partStart;      // partition -> first position
+        private readonly int[] partLen;
+        private readonly long[][] pow3;
+        private readonly double[][] popLoss;   // [part][code]
+        private readonly double[][][][] maxComp; // [part][i][prefixCode][r]
+        private readonly double[][] suffixBest;  // [part][r]: best combined bound over partitions > part
+
+        public long Leaves;
+        public long DpSolves;
+        public long OptSolves;
+        public long Nodes;
+
+        public ExactEnum(TeModel model, GapEval ev)
+        {
+            this.m = model;
+            this.levels = model.NumLevels;
+            this.budget = model.Density;
+            var parts = model.NumParts;
+            this.order = Enumerable.Range(0, parts).SelectMany(j => model.PartPairs[j]).ToArray();
+            this.posPart = new int[model.K];
+            this.posInPart = new int[model.K];
+            this.partStart = new int[parts];
+            this.partLen = new int[parts];
+            var pos = 0;
+            for (var j = 0; j < parts; j++)
+            {
+                this.partStart[j] = pos;
+                this.partLen[j] = model.PartPairs[j].Length;
+                for (var i = 0; i < this.partLen[j]; i++)
+                {
+                    this.posPart[pos] = j;
+                    this.posInPart[pos] = i;
+                    pos++;
+                }
+            }
+
+            this.pow3 = new long[parts][];
+            this.popLoss = new double[parts][];
+            this.maxComp = new double[parts][][][];
+            var lv = new int[model.K];
+            for (var j = 0; j < parts; j++)
+            {
+                var n = this.partLen[j];
+                this.pow3[j] = new long[n + 1];
+                this.pow3[j][0] = 1;
+                for (var i = 1; i <= n; i++)
+                {
+                    this.pow3[j][i] = this.pow3[j][i - 1] * this.levels;
+                }
+
+                var size = this.pow3[j][n];
+                var table = new double[size];
+                var pairs = model.PartPairs[j];
+                for (long c = 0; c < size; c++)
+                {
+                    var x = c;
+                    var total = 0.0;
+                    var nz = 0;
+                    for (var i = 0; i < n; i++)
+                    {
+                        var l = (int)(x % this.levels);
+                        x /= this.levels;
+                        lv[pairs[i]] = l;
+                        total += model.Levels[l];
+                        if (model.Levels[l] > 0)
+                        {
+                            nz++;
+                        }
+                    }
+
+                    table[c] = nz > this.budget ? double.NegativeInfinity : total - ev.PopPart(j, lv);
+                }
+
+                foreach (var k in pairs)
+                {
+                    lv[k] = 0;
+                }
+
+                this.popLoss[j] = table;
+
+                // maxComp[i][prefix][r]: assigned first i pairs (code prefix), best loss with <= r more nonzeros.
+                var mc = new double[n + 1][][];
+                mc[n] = new double[size][];
+                for (long c = 0; c < size; c++)
+                {
+                    var arr = new double[this.budget + 1];
+                    for (var r = 0; r <= this.budget; r++)
+                    {
+                        arr[r] = table[c];
+                    }
+
+                    mc[n][c] = arr;
+                }
+
+                for (var i = n - 1; i >= 0; i--)
+                {
+                    var sz = this.pow3[j][i];
+                    mc[i] = new double[sz][];
+                    for (long c = 0; c < sz; c++)
+                    {
+                        var arr = new double[this.budget + 1];
+                        for (var r = 0; r <= this.budget; r++)
+                        {
+                            var best = mc[i + 1][c][r];
+                            if (r > 0)
+                            {
+                                for (var l = 1; l < this.levels; l++)
+                                {
+                                    best = Math.Max(best, mc[i + 1][c + (l * sz)][r - 1]);
+                                }
+                            }
+
+                            arr[r] = best;
+                        }
+
+                        mc[i][c] = arr;
+                    }
+                }
+
+                this.maxComp[j] = mc;
+            }
+
+            // suffixBest[j][r] = max over splits of r among partitions j+1.. of their full bounds.
+            this.suffixBest = new double[parts][];
+            var acc = new double[this.budget + 1];
+            for (var j = parts - 1; j >= 0; j--)
+            {
+                this.suffixBest[j] = (double[])acc.Clone();
+                var full = this.maxComp[j][0][0];
+                var next = new double[this.budget + 1];
+                for (var r = 0; r <= this.budget; r++)
+                {
+                    var best = double.NegativeInfinity;
+                    for (var r1 = 0; r1 <= r; r1++)
+                    {
+                        best = Math.Max(best, full[r1] + acc[r - r1]);
+                    }
+
+                    next[r] = best;
+                }
+
+                acc = next;
+            }
+        }
+
+        /// <summary>Upper bound on POP loss over all vectors (any budget).</summary>
+        public double RootBound => this.Bound(0, 0.0, 0, this.budget);
+
+        private double Bound(int pos, double fixedLoss, long prefixCode, int remaining)
+        {
+            if (pos >= this.order.Length)
+            {
+                return fixedLoss;
+            }
+
+            var j = this.posPart[pos];
+            var cur = this.maxComp[j][this.posInPart[pos]][prefixCode];
+            var suf = this.suffixBest[j];
+            var best = double.NegativeInfinity;
+            for (var r1 = 0; r1 <= remaining; r1++)
+            {
+                var v = cur[r1] + suf[remaining - r1];
+                if (v > best)
+                {
+                    best = v;
+                }
+            }
+
+            return fixedLoss + best;
+        }
+
+        /// <summary>
+        /// Enumerate every vector whose gap can exceed the incumbent; returns false on timeout.
+        /// prefixFilter restricts the subtree to the given assignments of the first positions (for splitting work).
+        /// </summary>
+        public bool Run(GapEval ev, Incumbent inc, Stopwatch clock, long deadlineTicks, int[] prefix)
+        {
+            var lv = new int[this.m.K];
+            var pinLoad = new double[this.m.E];
+            var state = new DfsState { Ev = ev, Inc = inc, Clock = clock, Deadline = deadlineTicks, Lv = lv, PinLoad = pinLoad };
+            return this.Dfs(state, 0, 0.0, 0, this.budget, prefix);
+        }
+
+        private sealed class DfsState
+        {
+            public GapEval Ev;
+            public Incumbent Inc;
+            public Stopwatch Clock;
+            public long Deadline;
+            public int[] Lv;
+            public double[] PinLoad;
+            public bool TimedOut;
+            public int Counter;
+        }
+
+        private bool Dfs(DfsState st, int pos, double fixedLoss, long code, int remaining, int[] prefix)
+        {
+            this.Nodes++;
+            if ((++st.Counter & 1023) == 0 && st.Clock.ElapsedTicks > st.Deadline)
+            {
+                st.TimedOut = true;
+            }
+
+            if (st.TimedOut)
+            {
+                return false;
+            }
+
+            var threshold = st.Inc.Read() + 1e-9;
+            if (pos == this.order.Length)
+            {
+                this.Leaf(st, threshold);
+                return true;
+            }
+
+            var j = this.posPart[pos];
+            var i = this.posInPart[pos];
+            var k = this.order[pos];
+            var lastInPart = i == this.partLen[j] - 1;
+            var sz = this.pow3[j][i];
+            for (var l = 0; l < this.levels; l++)
+            {
+                if (prefix != null && pos < prefix.Length && prefix[pos] != l)
+                {
+                    continue;
+                }
+
+                var isNz = this.m.Levels[l] > 0;
+                if (isNz && remaining == 0)
+                {
+                    break;
+                }
+
+                // Incremental pin feasibility.
+                var pinned = this.m.IsPinnedLevel[l];
+                if (pinned)
+                {
+                    var d = this.m.Levels[l];
+                    var ok = true;
+                    foreach (var e in this.m.Path0[k])
+                    {
+                        if (st.PinLoad[e] + d > this.m.Cap[e] + 1e-7)
+                        {
+                            ok = false;
+                        }
+                    }
+
+                    if (!ok)
+                    {
+                        continue;
+                    }
+
+                    foreach (var e in this.m.Path0[k])
+                    {
+                        st.PinLoad[e] += d;
+                    }
+                }
+
+                var c2 = code + (l * sz);
+                var rem2 = remaining - (isNz ? 1 : 0);
+                st.Lv[k] = l;
+                bool cont;
+                if (lastInPart)
+                {
+                    var loss = fixedLoss + this.popLoss[j][c2];
+                    cont = this.Bound(pos + 1, loss, 0, rem2) > threshold;
+                    if (cont)
+                    {
+                        this.Dfs(st, pos + 1, loss, 0, rem2, prefix);
+                    }
+                }
+                else
+                {
+                    cont = this.Bound(pos + 1, fixedLoss, c2, rem2) > threshold;
+                    if (cont)
+                    {
+                        this.Dfs(st, pos + 1, fixedLoss, c2, rem2, prefix);
+                    }
+                }
+
+                st.Lv[k] = 0;
+                if (pinned)
+                {
+                    var d = this.m.Levels[l];
+                    foreach (var e in this.m.Path0[k])
+                    {
+                        st.PinLoad[e] -= d;
+                    }
+                }
+
+                threshold = st.Inc.Read() + 1e-9;
+            }
+
+            return !st.TimedOut;
+        }
+
+        private void Leaf(DfsState st, double threshold)
+        {
+            this.Leaves++;
+            var ev = st.Ev;
+            var lv = st.Lv;
+            var total = ev.Total(lv);
+            this.DpSolves++;
+            var dp = ev.Dp(lv);
+            if (total - dp <= threshold)
+            {
+                return;
+            }
+
+            var pop = ev.Pop(lv);
+            var heur = Math.Max(pop, dp);
+            this.OptSolves++;
+            var gap = ev.Opt(lv) - heur;
+            if (gap > threshold)
+            {
+                st.Inc.Offer(lv, gap, st.Clock);
+            }
+        }
+    }
+}
