@@ -0,0 +1,403 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Numerics;
+    using System.Runtime.CompilerServices;
+    using System.Runtime.InteropServices;
+
+    /// <summary>
+    /// Small dense simplex for the path-form max-flow LP:
+    /// max sum f  s.t.  sum_p f_kp &lt;= d_k,  sum_{kp uses e} f_kp &lt;= c_e,  f &gt;= 0.
+    /// A presolve removes edges that can never bind and pairs that own a path made only of
+    /// such edges (those pairs route their whole demand there).
+    /// </summary>
+    internal sealed class FlowLp
+    {
+        private const double PivotEps = 1e-9;
+        private readonly TeModel m;
+        private readonly double[] load;
+        private readonly double[] capRem;
+        private readonly int[] edgeRow;
+        private readonly int[] touched;
+        private readonly int[] remaining;
+        private readonly int[] next;
+        private readonly int[] colPair;
+        private double[] tab;
+        private int[] basicLabel;
+        private int[] nonbasicLabel;
+
+        public long Pivots;
+        public long Solves;
+
+        public FlowLp(TeModel model)
+        {
+            this.m = model;
+            this.load = new double[model.E];
+            this.capRem = new double[model.E];
+            this.edgeRow = new int[model.E];
+            this.touched = new int[model.E];
+            this.remaining = new int[model.K];
+            this.next = new int[model.K];
+            var maxCols = 0;
+            for (var k = 0; k < model.K; k++)
+            {
+                maxCols += model.Paths[k].Length;
+            }
+
+            this.colPair = new int[maxCols + 1];
+            var maxRows = model.K + model.E + 1;
+            this.tab = new double[(maxRows + 1) * (maxCols + 8)];
+            this.basicLabel = new int[maxRows + 1];
+            this.nonbasicLabel = new int[maxCols + 1];
+            for (var e = 0; e < model.E; e++)
+            {
+                this.edgeRow[e] = -1;
+            }
+        }
+
+        /// <summary>
+        /// Solve for the pairs in active[0..count) with demands dem[k] and capacities cap[e]*scale.
+        /// </summary>
+        public double Solve(int[] active, int count, double[] dem, double[] cap, double scale)
+        {
+            this.Solves++;
+            var md = this.m;
+            var nRem = 0;
+            var nTouched = 0;
+            for (var i = 0; i < count; i++)
+            {
+                var k = active[i];
+                if (dem[k] <= 0.0 || md.Paths[k].Length == 0)
+                {
+                    continue;
+                }
+
+                this.remaining[nRem++] = k;
+                foreach (var e in md.PairEdges[k])
+                {
+                    if (this.edgeRow[e] == -1)
+                    {
+                        this.edgeRow[e] = -2; // mark touched
+                        this.touched[nTouched++] = e;
+                        this.capRem[e] = cap[e] * scale;
+                    }
+                }
+            }
+
+            var fixedSum = 0.0;
+            while (true)
+            {
+                for (var t = 0; t < nTouched; t++)
+                {
+                    this.load[this.touched[t]] = 0.0;
+                }
+
+                for (var i = 0; i < nRem; i++)
+                {
+                    var k = this.remaining[i];
+                    var d = dem[k];
+                    foreach (var e in md.PairEdges[k])
+                    {
+                        this.load[e] += d;
+                    }
+                }
+
+                var nNext = 0;
+                var changed = false;
+                for (var i = 0; i < nRem; i++)
+                {
+                    var k = this.remaining[i];
+                    var paths = md.Paths[k];
+                    var freePath = -1;
+                    for (var p = 0; p < paths.Length && freePath < 0; p++)
+                    {
+                        var ok = true;
+                        foreach (var e in paths[p])
+                        {
+                            if (this.load[e] > this.capRem[e] + 1e-9)
+                            {
+                                ok = false;
+                                break;
+                            }
+                        }
+
+                        if (ok)
+                        {
+                            freePath = p;
+                        }
+                    }
+
+                    if (freePath >= 0)
+                    {
+                        fixedSum += dem[k];
+                        foreach (var e in paths[freePath])
+                        {
+                            this.capRem[e] -= dem[k];
+                        }
+
+                        changed = true;
+                    }
+                    else
+                    {
+                        this.next[nNext++] = k;
+                    }
+                }
+
+                Array.Copy(this.next, this.remaining, nNext);
+                nRem = nNext;
+                if (!changed || nRem == 0)
+                {
+                    break;
+                }
+            }
+
+            if (nRem == 0)
+            {
+                for (var t = 0; t < nTouched; t++)
+                {
+                    this.edgeRow[this.touched[t]] = -1;
+                }
+
+                return fixedSum;
+            }
+
+            // Recompute loads of the remaining pairs to find binding edges.
+            for (var t = 0; t < nTouched; t++)
+            {
+                this.load[this.touched[t]] = 0.0;
+            }
+
+            var nCols = 0;
+            for (var i = 0; i < nRem; i++)
+            {
+                var k = this.remaining[i];
+                foreach (var e in md.PairEdges[k])
+                {
+                    this.load[e] += dem[k];
+                }
+
+                nCols += md.Paths[k].Length;
+            }
+
+            var nRows = nRem;
+            for (var t = 0; t < nTouched; t++)
+            {
+                var e = this.touched[t];
+                if (this.load[e] > this.capRem[e] + 1e-9)
+                {
+                    this.edgeRow[e] = nRows++;
+                }
+            }
+
+            var w = nCols + 1;
+            var need = (nRows + 1) * w;
+            if (this.tab.Length < need)
+            {
+                this.tab = new double[need * 2];
+            }
+
+            var tb = this.tab;
+            Array.Clear(tb, 0, need);
+            var col = 0;
+            for (var i = 0; i < nRem; i++)
+            {
+                var k = this.remaining[i];
+                tb[(i * w) + nCols] = dem[k];
+                foreach (var path in md.Paths[k])
+                {
+                    tb[(i * w) + col] = 1.0;
+                    foreach (var e in path)
+                    {
+                        var r = this.edgeRow[e];
+                        if (r >= 0)
+                        {
+                            tb[(r * w) + col] += 1.0;
+                        }
+                    }
+
+                    tb[(nRows * w) + col] = -1.0;
+                    col++;
+                }
+            }
+
+            for (var t = 0; t < nTouched; t++)
+            {
+                var e = this.touched[t];
+                var r = this.edgeRow[e];
+                if (r >= 0)
+                {
+                    tb[(r * w) + nCols] = this.capRem[e] < 0 ? 0.0 : this.capRem[e];
+                }
+
+                this.edgeRow[e] = -1;
+            }
+
+            for (var j = 0; j < nCols; j++)
+            {
+                this.nonbasicLabel[j] = j;
+            }
+
+            for (var i = 0; i < nRows; i++)
+            {
+                this.basicLabel[i] = nCols + i;
+            }
+
+            var value = this.Simplex(nRows, nCols, w);
+            return value + fixedSum;
+        }
+
+        private double Simplex(int nRows, int nCols, int w)
+        {
+            var tb = this.tab;
+            var objRow = nRows * w;
+            var degenerateRun = 0;
+            var bland = false;
+            for (var iter = 0; ; iter++)
+            {
+                if (iter > 20000)
+                {
+                    throw new InvalidOperationException("simplex iteration limit");
+                }
+
+                var s = -1;
+                if (!bland)
+                {
+                    var best = -PivotEps;
+                    for (var j = 0; j < nCols; j++)
+                    {
+                        var v = tb[objRow + j];
+                        if (v < best)
+                        {
+                            best = v;
+                            s = j;
+                        }
+                    }
+                }
+                else
+                {
+                    var bestLabel = int.MaxValue;
+                    for (var j = 0; j < nCols; j++)
+                    {
+                        if (tb[objRow + j] < -PivotEps && this.nonbasicLabel[j] < bestLabel)
+                        {
+                            bestLabel = this.nonbasicLabel[j];
+                            s = j;
+                        }
+                    }
+                }
+
+                if (s < 0)
+                {
+                    break;
+                }
+
+                var r = -1;
+                var bestRatio = double.MaxValue;
+                for (var i = 0; i < nRows; i++)
+                {
+                    var a = tb[(i * w) + s];
+                    if (a > PivotEps)
+                    {
+                        var rhs = tb[(i * w) + nCols];
+                        var ratio = rhs / a;
+                        if (ratio < bestRatio - 1e-12 || (ratio <= bestRatio + 1e-12 && this.basicLabel[i] < this.basicLabel[r]))
+                        {
+                            bestRatio = ratio;
+                            r = i;
+                        }
+                    }
+                }
+
+                if (r < 0)
+                {
+                    throw new InvalidOperationException("unbounded flow LP");
+                }
+
+                if (bestRatio < 1e-12)
+                {
+                    degenerateRun++;
+                    if (degenerateRun > 25)
+                    {
+                        bland = true;
+                    }
+                }
+                else
+                {
+                    degenerateRun = 0;
+                }
+
+                this.Pivot(nRows, w, r, s);
+                (this.basicLabel[r], this.nonbasicLabel[s]) = (this.nonbasicLabel[s], this.basicLabel[r]);
+                this.Pivots++;
+            }
+
+            return tb[objRow + nCols];
+        }
+
+        [MethodImpl(MethodImplOptions.AggressiveInlining)]
+        private void Pivot(int nRows, int w, int r, int s)
+        {
+            var tb = this.tab;
+            var rowR = tb.AsSpan(r * w, w);
+            var p = rowR[s];
+            var inv = 1.0 / p;
+            for (var j = 0; j < w; j++)
+            {
+                rowR[j] *= inv;
+            }
+
+            rowR[s] = inv;
+            var rhsIndex = w - 1;
+            for (var i = 0; i <= nRows; i++)
+            {
+                if (i == r)
+                {
+                    continue;
+                }
+
+                var rowI = tb.AsSpan(i * w, w);
+                var f = rowI[s];
+                if (f == 0.0)
+                {
+                    continue;
+                }
+
+                AxpyNeg(rowI, rowR, f);
+                rowI[s] = -f * inv;
+                if (i < nRows)
+                {
+                    var rhs = rowI[rhsIndex];
+                    if (rhs < 0.0 && rhs > -1e-11)
+                    {
+                        rowI[rhsIndex] = 0.0;
+                    }
+                }
+            }
+        }
+
+        [MethodImpl(MethodImplOptions.AggressiveInlining)]
+        private static void AxpyNeg(Span<double> y, ReadOnlySpan<double> x, double f)
+        {
+            var n = y.Length;
+            var j = 0;
+            if (Vector.IsHardwareAccelerated && n >= Vector<double>.Count)
+            {
+                var vf = new Vector<double>(f);
+                var yv = MemoryMarshal.Cast<double, Vector<double>>(y);
+                var xv = MemoryMarshal.Cast<double, Vector<double>>(x);
+                for (var v = 0; v < yv.Length; v++)
+                {
+                    yv[v] -= vf * xv[v];
+                }
+
+                j = yv.Length * Vector<double>.Count;
+            }
+
+            for (; j < n; j++)
+            {
+                y[j] -= f * x[j];
+            }
+        }
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/GapEval.cs b/project/MetaOptimize/TrafficEngineering/Candidate/GapEval.cs
new file mode 100644
index 0000000..961b3f2
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/GapEval.cs
@@ -0,0 +1,308 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Concurrent;
+
+    /// <summary>
+    /// Shared cache of per-partition POP throughputs keyed by the partition's level sub-vector.
+    /// </summary>
+    internal sealed class PopCache
+    {
+        private readonly TeModel m;
+        private readonly double[][] arrays;
+        private readonly ConcurrentDictionary<long, double>[] maps;
+        private readonly long[][] pow;
+
+        public PopCache(TeModel model)
+        {
+            this.m = model;
+            this.arrays = new double[model.NumParts][];
+            this.maps = new ConcurrentDictionary<long, double>[model.NumParts];
+            this.pow = new long[model.NumParts][];
+            for (var j = 0; j < model.NumParts; j++)
+            {
+                var n = model.PartPairs[j].Length;
+                this.pow[j] = new long[n];
+                long size = 1;
+                var fits = true;
+                for (var i = 0; i < n; i++)
+                {
+                    this.pow[j][i] = size;
+                    if (size > (1L << 40) / model.NumLevels)
+                    {
+                        fits = false;
+                    }
+
+                    size *= model.NumLevels;
+                }
+
+                if (fits && size <= (1L << 21))
+                {
+                    this.arrays[j] = new double[size];
+                    Array.Fill(this.arrays[j], double.NaN);
+                }
+                else
+                {
+                    this.maps[j] = new ConcurrentDictionary<long, double>();
+                }
+            }
+        }
+
+        public long Key(int part, int[] lv)
+        {
+            var pairs = this.m.PartPairs[part];
+            var pw = this.pow[part];
+            long key = 0;
+            for (var i = 0; i < pairs.Length; i++)
+            {
+                key += lv[pairs[i]] * pw[i];
+            }
+
+            return key;
+        }
+
+        public bool TryGet(int part, long key, out double value)
+        {
+            var arr = this.arrays[part];
+            if (arr != null)
+            {
+                value = arr[key];
+                return !double.IsNaN(value);
+            }
+
+            return this.maps[part].TryGetValue(key, out value);
+        }
+
+        public void Set(int part, long key, double value)
+        {
+            var arr = this.arrays[part];
+            if (arr != null)
+            {
+                arr[key] = value;
+            }
+            else
+            {
+                this.maps[part][key] = value;
+            }
+        }
+    }
+
+    /// <summary>
+    /// Exact OPT / POP / DP replay with a private LP engine (one instance per thread).
+    /// </summary>
+    internal sealed class GapEval
+    {
+        public readonly TeModel M;
+        private readonly PopCache popCache;
+        private readonly FlowLp lp;
+        private readonly double[] dem;
+        private readonly double[] resid;
+        private readonly int[] active;
+        private readonly int[] pinnedCount;
+
+        public long Evaluations;
+        public long OptSolves;
+
+        public GapEval(TeModel model, PopCache cache)
+        {
+            this.M = model;
+            this.popCache = cache;
+            this.lp = new FlowLp(model);
+            this.dem = new double[model.K];
+            this.resid = new double[model.E];
+            this.active = new int[model.K];
+            this.pinnedCount = new int[model.E];
+        }
+
+        public FlowLp Lp => this.lp;
+
+        /// <summary>Total demand of a level vector.</summary>
+        public double Total(int[] lv)
+        {
+            var s = 0.0;
+            for (var k = 0; k < lv.Length; k++)
+            {
+                s += this.M.Levels[lv[k]];
+            }
+
+            return s;
+        }
+
+        public int NonZero(int[] lv)
+        {
+            var c = 0;
+            for (var k = 0; k < lv.Length; k++)
+            {
+                if (this.M.Levels[lv[k]] > 0.0)
+                {
+                    c++;
+                }
+            }
+
+            return c;
+        }
+
+        /// <summary>Pinned shortest-path load stays within capacity (1e-7 tolerance).</summary>
+        public bool PinFeasible(int[] lv)
+        {
+            var md = this.M;
+            Array.Clear(this.resid);
+            for (var k = 0; k < md.K; k++)
+            {
+                if (md.IsPinnedLevel[lv[k]])
+                {
+                    var d = md.Levels[lv[k]];
+                    foreach (var e in md.Path0[k])
+                    {
+                        this.resid[e] += d;
+                    }
+                }
+            }
+
+            for (var e = 0; e < md.E; e++)
+            {
+                if (this.resid[e] > md.Cap[e] + 1e-7)
+                {
+                    return false;
+                }
+            }
+
+            return true;
+        }
+
+        public double PopPart(int part, int[] lv)
+        {
+            var key = this.popCache.Key(part, lv);
+            if (this.popCache.TryGet(part, key, out var v))
+            {
+                return v;
+            }
+
+            var md = this.M;
+            var n = 0;
+            foreach (var k in md.PartPairs[part])
+            {
+                var d = md.Levels[lv[k]];
+                this.dem[k] = d;
+                if (d > 0.0)
+                {
+                    this.active[n++] = k;
+                }
+            }
+
+            v = n == 0 ? 0.0 : this.lp.Solve(this.active, n, this.dem, md.Cap, 1.0 / md.NumParts);
+            this.popCache.Set(part, key, v);
+            return v;
+        }
+
+        public double Pop(int[] lv)
+        {
+            var s = 0.0;
+            for (var j = 0; j < this.M.NumParts; j++)
+            {
+                s += this.PopPart(j, lv);
+            }
+
+            return s;
+        }
+
+        /// <summary>Demand pinning throughput (0 when pinning is infeasible, as the replay does).</summary>
+        public double Dp(int[] lv)
+        {
+            var md = this.M;
+            Array.Copy(md.Cap, this.resid, md.E);
+            var pinned = 0.0;
+            var n = 0;
+            for (var k = 0; k < md.K; k++)
+            {
+                var d = md.Levels[lv[k]];
+                this.dem[k] = d;
+                if (d <= 0.0)
+                {
+                    continue;
+                }
+
+                if (md.IsPinnedLevel[lv[k]])
+                {
+                    pinned += d;
+                    foreach (var e in md.Path0[k])
+                    {
+                        this.resid[e] -= d;
+                    }
+                }
+                else
+                {
+                    this.active[n++] = k;
+                }
+            }
+
+            for (var e = 0; e < md.E; e++)
+            {
+                if (this.resid[e] < -1e-7)
+                {
+                    return 0.0;
+                }
+
+                if (this.resid[e] < 0.0)
+                {
+                    this.resid[e] = 0.0;
+                }
+            }
+
+            return n == 0 ? pinned : pinned + this.lp.Solve(this.active, n, this.dem, this.resid, 1.0);
+        }
+
+        public double Opt(int[] lv)
+        {
+            var md = this.M;
+            var n = 0;
+            for (var k = 0; k < md.K; k++)
+            {
+                var d = md.Levels[lv[k]];
+                this.dem[k] = d;
+                if (d > 0.0)
+                {
+                    this.active[n++] = k;
+                }
+            }
+
+            this.OptSolves++;
+            return n == 0 ? 0.0 : this.lp.Solve(this.active, n, this.dem, md.Cap, 1.0);
+        }
+
+        /// <summary>Exact gap of a pin-feasible vector.</summary>
+        public double Gap(int[] lv)
+        {
+            this.Evaluations++;
+            var heur = Math.Max(this.Pop(lv), this.Dp(lv));
+            return Math.Max(0.0, this.Opt(lv) - heur);
+        }
+
+        /// <summary>
+        /// Exact gap when it can exceed <paramref name="threshold"/>; otherwise returns an
+        /// upper bound that is &lt;= threshold. Never under-reports a gap above threshold.
+        /// </summary>
+        public double GapAbove(int[] lv, double threshold)
+        {
+            this.Evaluations++;
+            var total = this.Total(lv);
+            var pop = this.Pop(lv);
+            var ub = total - pop;
+            if (ub <= threshold)
+            {
+                return ub;
+            }
+
+            var dp = this.Dp(lv);
+            var heur = Math.Max(pop, dp);
+            ub = total - heur;
+            if (ub <= threshold)
+            {
+                return ub;
+            }
+
+            return Math.Max(0.0, this.Opt(lv) - heur);
+        }
+    }
+}
