index 0000000..e020234
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/LocalSearch.cs
@@ -0,0 +1,265 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Generic;
+    using System.Diagnostics;
+    using System.Threading;
+
+    /// <summary>
+    /// Shared incumbent across search threads.
+    /// </summary>
+    internal sealed class Incumbent
+    {
+        private readonly object gate = new object();
+        public double Gap = -1.0;
+        public int[] Levels;
+        public long FoundAtTicks;
+
+        public bool Offer(int[] lv, double gap, Stopwatch clock)
+        {
+            if (gap <= this.Gap + 1e-9)
+            {
+                return false;
+            }
+
+            lock (this.gate)
+            {
+                if (gap <= this.Gap + 1e-9)
+                {
+                    return false;
+                }
+
+                this.Gap = gap;
+                this.Levels = (int[])lv.Clone();
+                this.FoundAtTicks = clock.ElapsedTicks;
+                return true;
+            }
+        }
+
+        public double Read() => Volatile.Read(ref this.Gap);
+    }
+
+    /// <summary>
+    /// Iterated local search over level vectors with add / drop / change / relocate moves.
+    /// </summary>
+    internal sealed class LocalSearch
+    {
+        private readonly GapEval ev;
+        private readonly TeModel m;
+        private readonly Random rng;
+        private readonly Incumbent inc;
+        private readonly Stopwatch clock;
+        private readonly Budget budget;
+        private readonly int[] cur;
+        private readonly int[] tmp;
+        private readonly int[] order;
+
+        public LocalSearch(GapEval ev, Incumbent inc, Budget budget, int seed)
+        {
+            this.ev = ev;
+            this.m = ev.M;
+            this.inc = inc;
+            this.budget = budget;
+            this.clock = budget.Clock;
+            this.rng = new Random(seed);
+            this.cur = new int[this.m.K];
+            this.tmp = new int[this.m.K];
+            this.order = new int[this.m.K];
+        }
+
+        public long Restarts;
+
+        private bool Valid(int[] lv)
+        {
+            return this.ev.NonZero(lv) <= this.m.Density && this.ev.PinFeasible(lv);
+        }
+
+        public int[] RandomVector()
+        {
+            var lv = new int[this.m.K];
+            this.RandomStart(lv);
+            return lv;
+        }
+
+        private void RandomStart(int[] lv)
+        {
+            while (true)
+            {
+                Array.Clear(lv);
+                var nz = this.m.Density - this.rng.Next(3);
+                for (var i = 0; i < nz; i++)
+                {
+                    lv[this.rng.Next(this.m.K)] = 1 + this.rng.Next(this.m.NumLevels - 1);
+                }
+
+                if (this.Valid(lv))
+                {
+                    return;
+                }
+            }
+        }
+
+        private void Shuffle(int[] a, int n)
+        {
+            for (var i = n - 1; i > 0; i--)
+            {
+                var j = this.rng.Next(i + 1);
+                (a[i], a[j]) = (a[j], a[i]);
+            }
+        }
+
+        /// <summary>
+        /// First-improvement descent from lv (in place). Returns the local optimum gap.
+        /// </summary>
+        public double Descend(int[] lv, double gap)
+        {
+            var md = this.m;
+            var improved = true;
+            while (improved && !this.budget.Expired())
+            {
+                improved = false;
+                var nz = this.ev.NonZero(lv);
+                for (var i = 0; i < md.K; i++)
+                {
+                    this.order[i] = i;
+                }
+
+                this.Shuffle(this.order, md.K);
+
+                // Single-pair level changes.
+                for (var oi = 0; oi < md.K && !improved; oi++)
+                {
+                    var k = this.order[oi];
+                    var old = lv[k];
+                    for (var l = 0; l < md.NumLevels && !improved; l++)
+                    {
+                        if (l == old)
+                        {
+                            continue;
+                        }
+
+                        if (old == 0 && l != 0 && nz >= md.Density)
+                        {
+                            continue;
+                        }
+
+                        lv[k] = l;
+                        if (this.ev.PinFeasible(lv))
+                        {
+                            var g = this.ev.GapAbove(lv, gap + 1e-9);
+                            if (g > gap + 1e-9)
+                            {
+                                gap = g;
+                                improved = true;
+                                this.inc.Offer(lv, gap, this.clock);
+                                break;
+                            }
+                        }
+
+                        lv[k] = old;
+                    }
+                }
+
+                if (improved)
+                {
+                    continue;
+                }
+
+                // Relocations: move a nonzero demand from a to an empty pair b with any level.
+                for (var oi = 0; oi < md.K && !improved; oi++)
+                {
+                    var a = this.order[oi];
+                    if (lv[a] == 0)
+                    {
+                        continue;
+                    }
+
+                    var la = lv[a];
+                    lv[a] = 0;
+                    for (var b = 0; b < md.K && !improved; b++)
+                    {
+                        if (b == a || lv[b] != 0)
+                        {
+                            continue;
+                        }
+
+                        for (var l = 1; l < md.NumLevels; l++)
+                        {
+                            lv[b] = l;
+                            if (this.ev.PinFeasible(lv))
+                            {
+                                var g = this.ev.GapAbove(lv, gap + 1e-9);
+                                if (g > gap + 1e-9)
+                                {
+                                    gap = g;
+                                    improved = true;
+                                    this.inc.Offer(lv, gap, this.clock);
+                                    break;
+                                }
+                            }
+
+                            lv[b] = 0;
+                        }
+                    }
+
+                    if (!improved)
+                    {
+                        lv[a] = la;
+                    }
+                }
+            }
+
+            return gap;
+        }
+
+        /// <summary>
+        /// Iterated local search until the deadline.
+        /// </summary>
+        public void Run()
+        {
+            var md = this.m;
+            var best = new int[md.K];
+            this.RandomStart(this.cur);
+            var curGap = this.ev.Gap(this.cur);
+            curGap = this.Descend(this.cur, curGap);
+            Array.Copy(this.cur, best, md.K);
+            var bestGap = curGap;
+            var stall = 0;
+            while (!this.budget.Expired())
+            {
+                // Perturb: change 2-4 random pairs.
+                Array.Copy(best, this.tmp, md.K);
+                var kicks = 2 + this.rng.Next(3);
+                for (var t = 0; t < kicks; t++)
+                {
+                    var k = this.rng.Next(md.K);
+                    this.tmp[k] = this.rng.Next(md.NumLevels);
+                }
+
+                if (!this.Valid(this.tmp))
+                {
+                    continue;
+                }
+
+                var g = this.ev.Gap(this.tmp);
+                g = this.Descend(this.tmp, g);
+                if (g > bestGap + 1e-9)
+                {
+                    bestGap = g;
+                    Array.Copy(this.tmp, best, md.K);
+                    stall = 0;
+                }
+                else if (++stall > 200)
+                {
+                    this.Restarts++;
+                    this.RandomStart(best);
+                    bestGap = this.Descend(best, this.ev.Gap(best));
+                    stall = 0;
+                }
+
+                this.inc.Offer(best, bestGap, this.clock);
+            }
+        }
+    }
+}
diff --git a/project/MetaOptimize/TrafficEngineering/Candidate/Portfolio.cs b/project/MetaOptimize/TrafficEngineering/Candidate/Portfolio.cs
new file mode 100644
index 0000000..ba85b83
--- /dev/null
+++ b/project/MetaOptimize/TrafficEngineering/Candidate/Portfolio.cs
@@ -0,0 +1,198 @@
+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Generic;
+    using System.Linq;
+    using System.Threading;
+
+    /// <summary>
+    /// Pool of distinct good vectors shared by the search threads.
+    /// </summary>
+    internal sealed class ElitePool
+    {
+        private readonly object gate = new object();
+        private readonly int capacity;
+        private readonly List<(double gap, int[] lv, string key)> items = new List<(double, int[], string)>();
+
+        public ElitePool(int capacity)
+        {
+            this.capacity = capacity;
+        }
+
+        public void Offer(int[] lv, double gap)
+        {
+            var key = string.Concat(lv);
+            lock (this.gate)
+            {
+                foreach (var it in this.items)
+                {
+                    if (it.key == key)
+                    {
+                        return;
+                    }
+                }
+
+                if (this.items.Count >= this.capacity && gap <= this.items[this.items.Count - 1].gap)
+                {
+                    return;
+                }
+
+                this.items.Add((gap, (int[])lv.Clone(), key));
+                this.items.Sort((a, b) => b.gap.CompareTo(a.gap));
+                if (this.items.Count > this.capacity)
+                {
+                    this.items.RemoveAt(this.items.Count - 1);
+                }
+            }
+        }
+
+        public (double gap, int[] lv) Pick(Random rng)
+        {
+            lock (this.gate)
+            {
+                if (this.items.Count == 0)
+                {
+                    return (-1.0, null);
+                }
+
+                // Bias toward the best entries.
+                var i = Math.Min(this.items.Count - 1, (int)(this.items.Count * rng.NextDouble() * rng.NextDouble()));
+                return (this.items[i].gap, (int[])this.items[i].lv.Clone());
+            }
+        }
+
+        public List<(double gap, int[] lv)> Snapshot()
+        {
+            lock (this.gate)
+            {
+                return this.items.Select(x => (x.gap, (int[])x.lv.Clone())).ToList();
+            }
+        }
+    }
+
+    /// <summary>
+    /// Search driver: every thread scores its slice of the cut seeds and descends from its best
+    /// seeds, then all threads run elite-pool iterated local search until the budget expires.
+    /// </summary>
+    internal sealed class Portfolio
+    {
+        private readonly TeModel m;
+        private readonly PopCache cache;
+        private readonly Incumbent inc;
+        private readonly Budget budget;
+        private readonly ElitePool pool = new ElitePool(24);
+        private int nextSlice;
+
+        public int SeedOffset;
+
+        public Portfolio(TeModel model, PopCache cache, Incumbent inc, Budget budget)
+        {
+            this.m = model;
+            this.cache = cache;
+            this.inc = inc;
+            this.budget = budget;
+        }
+
+        public ElitePool Pool => this.pool;
+
+        /// <summary>Score this thread's slice of the cut seeds exactly; best first.</summary>
+        private List<int[]> BuildSeeds(GapEval ev, int stride, int offset)
+        {
+            var seeder = new CutSeeder(this.m);
+            var raw = seeder.Generate(4, (30000 / stride) + 1, this.budget.Expired, stride, offset);
+            var scored = new List<(double g, int[] lv)>();
+            foreach (var lv in raw)
+            {
+                if (this.budget.Expired())
+                {
+                    break;
+                }
+
+                if (ev.NonZero(lv) > this.m.Density || !ev.PinFeasible(lv))
+                {
+                    continue;
+                }
+
+                var g = ev.Gap(lv);
+                scored.Add((g, lv));
+                this.inc.Offer(lv, g, this.budget.Clock);
+            }
+
+            return scored.OrderByDescending(x => x.g).Select(x => x.lv).Take((400 / stride) + 10).ToList();
+        }
+
+        public void Work(int id, int threads)
+        {
+            threads = Math.Max(1, threads);
+            var ev = new GapEval(this.m, this.cache);
+            var ls = new LocalSearch(ev, this.inc, this.budget, (7919 * (id + 1)) + this.SeedOffset);
+            var ds = new DeepSearch(ev, this.inc, this.budget, (104729 * (id + 1)) + this.SeedOffset);
+            var rng = new Random(31337 + id + this.SeedOffset);
+
+            // Phase A/B: claim slices of the cut enumeration; descend from each slice's best seeds.
+            var slices = 4 * threads;
+            while (!this.budget.Expired())
+            {
+                var slice = Interlocked.Increment(ref this.nextSlice) - 1;
+                if (slice >= slices)
+                {
+                    break;
+                }
+
+                foreach (var seed in this.BuildSeeds(ev, slices, slice))
+                {
+                    if (this.budget.Expired())
+                    {
+                        break;
+                    }
+
+                    var g = ls.Descend(seed, ev.Gap(seed));
+                    this.pool.Offer(seed, g);
+                }
+            }
+
+            // Phase C: elite-pool ILS with occasional deep (2-change) descents and random restarts.
+            var iter = 0;
+            while (!this.budget.Expired())
+            {
+                iter++;
+                int[] lv;
+                double g;
+                if (iter % 10 == 0)
+                {
+                    lv = ls.RandomVector();
+                    g = ls.Descend(lv, ev.Gap(lv));
+                    this.pool.Offer(lv, g);
+                    continue;
+                }
+
+                var pick = this.pool.Pick(rng);
+                if (pick.lv == null)
+                {
+                    lv = ls.RandomVector();
+                    g = ev.Gap(lv);
+                }
+                else
+                {
+                    lv = pick.lv;
+                    var kicks = 1 + rng.Next(4);
+                    for (var t = 0; t < kicks; t++)
+                    {
+                        lv[rng.Next(this.m.K)] = rng.Next(this.m.NumLevels);
+                    }
+
+                    if (ev.NonZero(lv) > this.m.Density || !ev.PinFeasible(lv))
+                    {
+                        continue;
+                    }
+
+                    g = ev.Gap(lv);
+                }
+
+                g = iter % 3 == 0 ? ds.Descend(lv, g) : ls.Descend(lv, g);
+                this.pool.Offer(lv, g);
+            }
+        }
+    }
+}
