+#pragma warning disable
+namespace MetaOptimize
+{
+    using System;
+    using System.Collections.Generic;
+    using System.Linq;
+
+    /// <summary>
+    /// Compact, read-only view of an adversarial search instance.
+    /// </summary>
+    internal sealed class TeModel
+    {
+        public int E;
+        public int K;
+        public double[] Cap;
+        public int[][][] Paths;      // [pair][path] -> edge indices
+        public int[][] PairEdges;    // [pair] -> distinct edges over all its paths
+        public int[][] Path0;        // [pair] -> shortest path edges
+        public int[] Partition;
+        public int NumParts;
+        public double[] Levels;
+        public double Threshold;
+        public int Density;
+        public int NumLevels;
+        public bool[] IsPinnedLevel; // level index -> pinned by demand pinning
+        public int[][] PartPairs;    // partition -> pair list
+
+        public TeModel(AdversarialSearchInstance inst)
+        {
+            this.E = inst.Edges.Length;
+            this.K = inst.Pairs.Length;
+            this.Cap = inst.Edges.Select(e => e.Capacity).ToArray();
+            this.Paths = new int[this.K][][];
+            this.PairEdges = new int[this.K][];
+            this.Path0 = new int[this.K][];
+            this.Partition = new int[this.K];
+            this.NumParts = Math.Max(1, inst.PopPartitions);
+            for (var k = 0; k < this.K; k++)
+            {
+                var pr = inst.Pairs[k];
+                var paths = pr.Paths ?? Array.Empty<int[]>();
+                this.Paths[k] = paths.Select(p => p.ToArray()).ToArray();
+                this.Path0[k] = paths.Length > 0 ? paths[0].ToArray() : Array.Empty<int>();
+                this.PairEdges[k] = paths.SelectMany(p => p).Distinct().OrderBy(x => x).ToArray();
+                this.Partition[k] = pr.Partition >= 0 && pr.Partition < this.NumParts ? pr.Partition : -1;
+            }
+
+            this.Levels = inst.Levels.ToArray();
+            this.NumLevels = this.Levels.Length;
+            this.Threshold = inst.PinningThreshold;
+            this.Density = inst.DensityLimit;
+            this.IsPinnedLevel = this.Levels.Select(v => v > 0.0 && v <= this.Threshold + 1e-7).ToArray();
+            this.PartPairs = new int[this.NumParts][];
+            for (var j = 0; j < this.NumParts; j++)
+            {
+                this.PartPairs[j] = Enumerable.Range(0, this.K).Where(k => this.Partition[k] == j).ToArray();
+            }
+        }
+    }
+}
